""" Returns the missing number from array A [1...N+1] with len(A) = N
    Should work in O(N)

    :param A: Input array (int)
    :returns: Missing value (int)
    :rtype: Integer

    """
def solution(A: Any) -> object {
    if (len(A) == 0) {
        return 1;
    }
    A.sort();
    ind = 1;
    while (A[(ind - 1)] == ind) {
        if (ind == len(A)) {
            return (ind + 1);
        }
        ind += 1;
    }
    return ind;
}

"""
    Find all indices of patterns in a string

    Parameters
    ----------
    string : str
        input string
    pattern : str
        string pattern to search

    Returns
    -------
    ind : list
        list of starting indices
    """
def find_str(string: str, pattern: str) -> list {
    import re;
    if not pattern.isalpha() {
        pattern = "\\" + pattern;
    }
    ind = [m.start() for m in re.finditer(pattern, string)];
    return ind;
}

