	:param temp: int, the new temperature data
	:return: int, the lower one between high and temp, which becomes the lowest temperature
	"""
def lower(low: Any, temp: Any) -> object {
    if (temp < low) {
        return temp;
    }
    return low;
}

"""
    Function to adds two arrays element-wise
    Returns the a new array with the result
    """
def add_arrays(arr1: Any, arr2: Any) -> object {
    if (len(arr1) == len(arr2)) {
        return [(arr1[i] + arr2[i]) for i in range(len(arr1))];
    }
    return None;
}
